import axios from 'axios';

// Read the Pixabay API key from Vite environment variables.
// Create a local `.env` with `VITE_PIXABAY_KEY=your_key` and do NOT commit it.
const API_KEY = import.meta.env.VITE_PIXABAY_KEY;
const BASE_URL = 'https://pixabay.com/api/';

if (!API_KEY) {
  console.warn('VITE_PIXABAY_KEY is not set. Add it to a local .env file.');
}

export function getImagesByQuery(query) {
  return axios
    .get(BASE_URL, {
      params: {
        key: API_KEY,
        q: query,
        image_type: 'photo',
        orientation: 'horizontal',
        safesearch: true,
        per_page: 40,
      },
    })
    .then(response => response.data);
}
